export function getInitialWordsWithDefaults(): Word[] {
  const now = new Date().toISOString();
  return (INITIAL_WORDS as any[]).map((w) => ({
    ...w,
    leitnerBox: 1,
    timesReviewed: 0,
    timesCorrect: 0,
    timesIncorrect: 0,
    streak: 0,
    nextReview: now
  }));
}
